"""Auto-generated licence registry (`LICENSES.md`)."""

from __future__ import annotations

from synergyrx_data.config import Settings
from synergyrx_data.connectors import REGISTRY, is_enabled, source_names
from synergyrx_data.manifest import Manifest

HEADER = """# Data licences

Generated by `synergyrx report` from the connector registry and `manifest.json`. Do not edit
by hand: change the connector's `SourceInfo` instead.

This file covers the **data** the pipeline collects, not the pipeline's own code. Raw data is
never committed (`data/` is git-ignored). Before publishing a model, a dataset or a figure,
check the row of every source that contributed to it, and cite each one.
"""


def _cell(text: str | None) -> str:
    return (text or "").replace("|", "\\|").replace("\n", " ")


def render_licenses(settings: Settings, manifest: Manifest) -> str:
    lines = [
        HEADER,
        "| Source | Licence | Terms | Enabled | Collected | Redistribution |",
        "|---|---|---|---|---|---|",
    ]
    for name in source_names():
        info = REGISTRY[name].info
        raw = [e for e in manifest.for_source(name) if e.layer in ("raw", "manual")]
        collected = (
            f"{len(raw)} file(s), last {max(e.retrieved_at for e in raw)[:10]}" if raw else "no"
        )
        licence = f"[{info.license}]({info.license_url})" if info.license_url else info.license
        terms = f"[terms]({info.terms_url})" if info.terms_url else ""
        lines.append(
            f"| **{name}**: {_cell(info.title)} | {_cell(licence)} | {terms} | "
            f"{'yes' if is_enabled(name, settings) else 'no'} | {collected} | "
            f"{_cell(info.redistribution)} |"
        )
    lines += ["", "## How to cite", ""]
    for name in source_names():
        lines.append(f"- **{name}**: {REGISTRY[name].info.citation}")
    lines += [
        "",
        "## Notes that affect how the data may be used",
        "",
    ]
    for name in source_names():
        info = REGISTRY[name].info
        if info.notes:
            lines.append(f"- **{name}**: {info.notes}")
    return "\n".join(lines) + "\n"


def write_licenses(settings: Settings, manifest: Manifest) -> str:
    path = settings.resolve(settings.licenses_path)
    text = render_licenses(settings, manifest)
    if not path.is_file() or path.read_text(encoding="utf-8") != text:
        path.write_text(text, encoding="utf-8")
    return settings.relative(path)
